/**
 * @name Untrusted data to pickle
 * @description Tracing data flow from public API parameters to pickle.load
 * @kind path-problem
 * @problem.severity error
 * @id py/pickle-rce-trace
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleFlowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider parameters of public functions as sources
    exists(Function f |
      f.getName().regexpMatch("^[a-zA-Z].*") and // Public function
      source instanceof DataFlow::ParameterNode and
      source.getScope() = f
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getLocation().getFile().getRelativePath().matches("%cache_metadata.py") and
      (
        call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module PickleFlow = TaintTracking::Global<PickleFlowConfig>;
import PickleFlow::PathGraph

from PickleFlow::PathNode source, PickleFlow::PathNode sink
where PickleFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle deserialization from $@.", source.getNode(), "public parameter"

/**
 * @name Unsafe pickle deserialization dataflow
 * @description Tracing data flow to pickle.load in cache_metadata.py
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-pickle-flow
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleFlowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Broad source: any parameter to a function in the module, or file reads
    source instanceof DataFlow::ParameterNode or
    source = API::moduleImport("builtins").getMember("open").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
        call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() and
        sink = call.getArg(0)
    )
  }
}

module PickleFlow = TaintTracking::Global<PickleFlowConfig>;
import PickleFlow::PathGraph

from PickleFlow::PathNode source, PickleFlow::PathNode sink
where PickleFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle deserialization from $@", source.getNode(), "source"

/**
 * @name Potential path traversal
 * @description distinct from previous attempts, this query identifies flow from function parameters to file open via os.path.join
 * @kind problem
 * @problem.severity warning
 * @id py/simple-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
  }

  predicate isAdditionalFlowStep(DataFlow::Node node1, DataFlow::Node node2) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("path").getMember("join").getACall() and
      node1 = call.getArg(_) and
      node2 = call
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;

from DataFlow::Node source, DataFlow::Node sink
where PathTraversalFlow::flow(source, sink)
select sink, "File open with path derived from parameter $@.", source, source.toString()
